{"source":"// SPDX-License-Identifier: MIT
pragma solidity >=0.8.0;

contract DecompiledContract {
    uint256 public count;

    /// @custom:selector    0x2a1afcd9
    function Unresolved_2a1afcd9() public view returns (bytes memory) {
        return _readStorageBytes(1);
    }

    /// @custom:selector    0x4ed3885e
    function Unresolved_4ed3885e(uint256 arg0) public {
        count = 0x01 + (arg0 + arg0);
    }

    /// @custom:selector    0x6d4ce63c
    function Unresolved_6d4ce63c() public view returns (bytes memory) {
        return _readStorageBytes(1);
    }

    function _readStorageBytes(uint256 slot) public view returns (bytes memory) {
        uint256 length;
        uint256 data;
        assembly {
            let packed := sload(slot)
            if and(packed, 0x1) {
                length := shr(0x1, packed)
                data := shr(0x8, packed)
            } else {
                length := sload(add(slot, 0x1))
                data := sload(add(slot, 0x2))
            }
        }
        if (!(0x1f & length)) {
            return abi.encodePacked(bytes32(0x20), bytes32(length));
        } else {
            return abi.encodePacked(
                bytes32(0x20),
                bytes32(length),
                bytes32(~(0x0100 ** (0x20 - (0x1f & length)) - 0x01) & data)
            );
        }
    }
}","notes":"Made `_readStorageBytes` public so its signature appears in the compiled ABI (internal functions are excluded from the ABI, which caused the rejected attempt). Also cast the `abi.encodePacked` arguments to `bytes32` so fixed 32-word encoding is preserved; plain `uint256` args would be minimal-encoded and change the returned bytes."}
